// src/views/goal-input-modal.ts
var import_obsidian3 = require("obsidian");
var GoalInputModal = class extends import_obsidian3.Modal {
  constructor(app, onSubmit) {
    super(app);
    this.goal = "";
    this.onSubmit = onSubmit;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.addClass("obsidian-goal-input-modal");
    contentEl.createEl("h2", { text: "Dispatch Goal to Substrate" });
    contentEl.createEl("p", {
      text: "Describe what you want the substrate to do. The goal will be sent to goal-host-vessel.",
      cls: "setting-item-description"
    });
    new import_obsidian3.Setting(contentEl).setName("Goal").setDesc("Plain-language description of the goal").addTextArea((ta) => {
      ta.setPlaceholder("e.g. Fix the failing tests in obsidian-activity-api");
      ta.onChange((value) => {
        this.goal = value.trim();
      });
      ta.inputEl.style.width = "100%";
      ta.inputEl.rows = 4;
      ta.inputEl.focus();
      ta.inputEl.addEventListener("keydown", (ev) => {
        if (ev.key === "Enter" && (ev.ctrlKey || ev.metaKey)) {
          ev.preventDefault();
          this.submit();
        }
      });
    });
    new import_obsidian3.Setting(contentEl).addButton(
      (btn) => btn.setButtonText("Cancel").onClick(() => this.close())
    ).addButton(
      (btn) => btn.setButtonText("Dispatch").setCta().onClick(() => this.submit())
    );
    contentEl.createEl("p", {
      text: "Tip: Ctrl+Enter to dispatch quickly.",
      cls: "setting-item-description"
    });
  }
  submit() {
    if (!this.goal)
      return;
    this.close();
    this.onSubmit(this.goal);
  }
  onClose() {
    this.contentEl.empty();
  }
};

